args.Content:
/* ==========================================================================
   Student Shelter - Shared Stylesheet
   Palette: Navy, Teal, and Amber
   ========================================================================== */

:root {
  --ss-navy: #0f2342;
  --ss-navy-light: #1a3660;
  --ss-navy-dark: #09172e;
  --ss-teal: #0d9488;
  --ss-teal-light: #14b8a6;
  --ss-teal-soft: #e6f7f5;
  --ss-amber: #f59e0b;
  --ss-amber-hover: #d97706;
  --ss-amber-soft: #fef3c7;
  --ss-bg: #f8fafc;
  --ss-surface: #ffffff;
  --ss-text: #1e293b;
  --ss-muted: #64748b;
  --ss-border: #dbe4ee;
  --ss-radius: 0.75rem;
  --ss-shadow: 0 8px 24px rgba(15, 35, 66, 0.08);
}

/* Base & Sticky Footer Layout */
html,
body {
  height: 100%;
}

body {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background-color: var(--ss-bg);
  color: var(--ss-text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.6;
}

main {
  flex: 1 0 auto;
}

a {
  color: var(--ss-teal);
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
}

a:hover {
  color: var(--ss-navy);
}

/* Brand Logo Placeholder Box */
.logo-placeholder {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 0.55rem;
  background: linear-gradient(135deg, var(--ss-teal), var(--ss-amber));
  color: var(--ss-navy-dark);
  font-weight: 800;
  font-size: 1rem;
  letter-spacing: 0.04em;
  border: 2px solid rgba(255, 255, 255, 0.28);
  flex-shrink: 0;
}

.brand-title {
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: 0.01em;
  color: #ffffff;
}

/* Shared Header & Navigation */
.site-header {
  background-color: var(--ss-navy);
  border-bottom: 3px solid var(--ss-teal);
  transition: box-shadow 0.2s ease;
  z-index: 1030;
}

.site-header.is-scrolled {
  box-shadow: 0 6px 20px rgba(9, 23, 46, 0.25);
}

.site-header .navbar {
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
}

.site-header .navbar-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
}

.site-header .navbar-nav {
  gap: 0.25rem;
}

.site-header .nav-link {
  color: rgba(255, 255, 255, 0.86);
  font-weight: 500;
  padding: 0.5rem 0.85rem;
  border-radius: 0.5rem;
  position: relative;
}

.site-header .nav-link:hover,
.site-header .nav-link:focus-visible {
  color: #ffffff;
  background-color: rgba(20, 184, 166, 0.16);
}

.site-header .nav-link.active {
  color: #ffffff;
  background-color: var(--ss-teal);
  font-weight: 600;
  box-shadow: inset 0 -3px 0 var(--ss-amber);
}

.site-header .navbar-toggler {
  border-color: rgba(255, 255, 255, 0.35);
}

.site-header .navbar-toggler:focus {
  box-shadow: 0 0 0 0.2rem rgba(245, 158, 11, 0.45);
}

/* Buttons */
.btn-amber {
  background-color: var(--ss-amber);
  border-color: var(--ss-amber);
  color: var(--ss-navy-dark);
  font-weight: 700;
}

.btn-amber:hover,
.btn-amber:focus-visible {
  background-color: var(--ss-amber-hover);
  border-color: var(--ss-amber-hover);
  color: var(--ss-navy-dark);
}

.btn-amber.active {
  box-shadow: 0 0 0 3px rgba(20, 184, 166, 0.7);
}

.btn-teal {
  background-color: var(--ss-teal);
  border-color: var(--ss-teal);
  color: #ffffff;
  font-weight: 600;
}

.btn-teal:hover,
.btn-teal:focus-visible {
  background-color: #0f766e;
  border-color: #0f766e;
  color: #ffffff;
}

.btn-outline-navy {
  color: var(--ss-navy);
  border-color: var(--ss-navy);
  font-weight: 600;
}

.btn-outline-navy:hover,
.btn-outline-navy:focus-visible {
  background-color: var(--ss-navy);
  color: #ffffff;
}

/* Shared Hero & Page Header Banners */
.hero-banner {
  background: linear-gradient(135deg, var(--ss-navy) 0%, var(--ss-navy-light) 60%, #115e59 100%);
  color: #ffffff;
  padding: 4rem 0;
}

.page-banner {
  background: linear-gradient(120deg, var(--ss-navy) 0%, var(--ss-navy-light) 75%, var(--ss-teal) 100%);
  color: #ffffff;
  padding: 2.75rem 0;
  border-bottom: 4px solid var(--ss-amber);
}

.badge-amber {
  background-color: var(--ss-amber-soft);
  color: #92400e;
  font-weight: 600;
}

.badge-teal {
  background-color: var(--ss-teal-soft);
  color: #0f766e;
  font-weight: 600;
}

/* Cards & Simple Placeholder Boxes */
.shelter-card {
  background-color: var(--ss-surface);
  border: 1px solid var(--ss-border);
  border-radius: var(--ss-radius);
  box-shadow: var(--ss-shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  overflow: hidden;
}

.shelter-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(15, 35, 66, 0.12);
}

.placeholder-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: repeating-linear-gradient(
    -45deg,
    #e2e8f0,
    #e2e8f0 12px,
    #edf2f7 12px,
    #edf2f7 24px
  );
  border: 2px dashed #94a3b8;
  color: var(--ss-navy);
  font-weight: 600;
  padding: 1.25rem;
  min-height: 190px;
}

.placeholder-box--tall {
  min-height: 290px;
}

.placeholder-box--card {
  border-left: 0;
  border-right: 0;
  border-top: 0;
  border-radius: 0;
}

.placeholder-box__label {
  font-size: 0.95rem;
  color: var(--ss-navy);
}

.placeholder-box__sub {
  font-size: 0.8rem;
  color: var(--ss-muted);
  margin-top: 0.25rem;
}

.section-heading {
  color: var(--ss-navy);
  font-weight: 700;
}

.text-navy {
  color: var(--ss-navy);
}

.text-teal {
  color: var(--ss-teal);
}

.text-amber {
  color: var(--ss-amber-hover);
}

/* Shared Footer */
.site-footer {
  background-color: var(--ss-navy-dark);
  color: rgba(255, 255, 255, 0.86);
  border-top: 4px solid var(--ss-amber);
  padding: 2.5rem 0 1.5rem;
}

.site-footer .footer-tagline {
  color: #cbd5e1;
  font-size: 0.92rem;
  margin: 0.35rem 0 0;
}

.site-footer .social-links {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.site-footer .social-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.1);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.16);
  text-decoration: none;
}

.site-footer .social-link:hover,
.site-footer .social-link:focus-visible {
  background-color: var(--ss-teal);
  border-color: var(--ss-teal-light);
  color: #ffffff;
}

.site-footer .footer-nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.75rem;
}

.site-footer .footer-nav a {
  color: #e2e8f0;
  text-decoration: none;
  font-size: 0.95rem;
  font-weight: 500;
}

.site-footer .footer-nav a:hover,
.site-footer .footer-nav a:focus-visible {
  color: var(--ss-amber);
  text-decoration: underline;
}

.site-footer .footer-nav a.active {
  color: var(--ss-amber);
  font-weight: 700;
}

.site-footer .footer-divider {
  color: rgba(255, 255, 255, 0.35);
  user-select: none;
}

.site-footer .footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  margin-top: 1.75rem;
  padding-top: 1rem;
  font-size: 0.85rem;
  color: #94a3b8;
}

@media (min-width: 992px) {
  .site-header .nav-item + .nav-item::before {
    content: "|";
    color: rgba(255, 255, 255, 0.25);
    margin-right: 0.25rem;
    align-self: center;
  }

  .site-header .nav-item {
    display: flex;
    align-items: center;
  }
}

/**
 * Student Shelter - Shared JavaScript
 * Injects shared header & footer with relative paths, highlights active page,
 * and handles common interactive behaviors across all pages.
 */

(function () {
  "use strict";

  const NAV_ITEMS = [
    { key: "home", label: "Home", path: "index.html" },
    { key: "about", label: "About us", path: "pages/about.html" },
    { key: "find-hostel", label: "Find a Hostel", path: "pages/find-hostel.html" },
    { key: "hostels", label: "Hostels", path: "pages/hostels.html" },
    { key: "rooms", label: "Rooms", path: "pages/rooms.html" },
    { key: "contact", label: "Contact us", path: "pages/contact.html" }
  ];

  const FOOTER_ITEMS = [
    { key: "home", label: "Home", path: "index.html" },
    { key: "about", label: "About us", path: "pages/about.html" },
    { key: "find-hostel", label: "Find a Hostel", path: "pages/find-hostel.html" },
    { key: "contact", label: "Contact us", path: "pages/contact.html" }
  ];

  const SOCIAL_LINKS = [
    {
      name: "Facebook",
      href: "#facebook",
      svg: '<svg width="18" height="18" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path d="M13.5 22v-8h2.7l.4-3h-3.1V9.1c0-.9.3-1.5 1.6-1.5h1.6V4.9c-.3 0-1.3-.1-2.4-.1-2.4 0-4 1.4-4 4.1V11H7.5v3h2.8v8h3.2z"/></svg>'
    },
    {
      name: "Instagram",
      href: "#instagram",
      svg: '<svg width="18" height="18" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path d="M7.5 2h9A5.5 5.5 0 0 1 22 7.5v9a5.5 5.5 0 0 1-5.5 5.5h-9A5.5 5.5 0 0 1 2 16.5v-9A5.5 5.5 0 0 1 7.5 2zm0 2A3.5 3.5 0 0 0 4 7.5v9A3.5 3.5 0 0 0 7.5 20h9a3.5 3.5 0 0 0 3.5-3.5v-9A3.5 3.5 0 0 0 16.5 4h-9zm9.75 1.5a1.25 1.25 0 1 1 0 2.5 1.25 1.25 0 0 1 0-2.5zM12 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6z"/></svg>'
    },
    {
      name: "Email",
      href: "mailto:info@studentshelter.example",
      svg: '<svg width="18" height="18" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2zm0 2v.4l8 5.3 8-5.3V7H4zm16 10V9.8l-7.4 4.9a1.1 1.1 0 0 1-1.2 0L4 9.8V17h16z"/></svg>'
    },
    {
      name: "LinkedIn",
      href: "#linkedin",
      svg: '<svg width="18" height="18" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path d="M6.94 8.5H3.56V19.5H6.94V8.5ZM5.25 3.5C4.14 3.5 3.25 4.39 3.25 5.5C3.25 6.6 4.14 7.5 5.25 7.5C6.35 7.5 7.25 6.6 7.25 5.5C7.25 4.39 6.35 3.5 5.25 3.5ZM20.44 13.02C20.44 9.88 18.76 8.22 16.16 8.22C14.37 8.22 13.48 9.2 13.02 9.93V8.5H9.65C9.7 9.48 9.65 19.5 9.65 19.5H13.02V13.36C13.02 13.02 13.05 12.69 13.15 12.45C13.42 11.78 14.03 11.09 15.07 11.09C16.41 11.09 17.06 12.11 17.06 13.6V19.5H20.44V13.02Z"/></svg>'
    }
  ];

  /**
   * Computes relative path prefix ('.' at root or '..' inside pages/).
   */
  function getRootPrefix() {
    const bodyRoot = document.body.getAttribute("data-root");
    if (bodyRoot) {
      return bodyRoot.replace(/\/+$/, "");
    }
    const path = window.location.pathname.replace(/\\/g, "/");
    return path.includes("/pages/") ? ".." : ".";
  }

  /**
   * Resolves a root-relative path using the page's relative prefix.
   */
  function resolveRelPath(rootPrefix, targetPath) {
    if (rootPrefix === ".") {
      return targetPath;
    }
    if (targetPath.startsWith("pages/")) {
      return targetPath.slice("pages/".length);
    }
    return rootPrefix + "/" + targetPath;
  }

  /**
   * Determines the active page key from body[data-page] or the URL filename.
   */
  function getCurrentPageKey() {
    const bodyPage = document.body.getAttribute("data-page");
    if (bodyPage) {
      return bodyPage;
    }
    const fileName = (window.location.pathname.split("/").pop() || "index.html").toLowerCase();
    const map = {
      "index.html": "home",
      "": "home",
      "about.html": "about",
      "find-hostel.html": "find-hostel",
      "hostels.html": "hostels",
      "rooms.html": "rooms",
      "contact.html": "contact",
      "login.html": "login"
    };
    return map[fileName] || "";
  }

  /**
   * Renders the shared header inside <header id="site-header">.
   */
  function renderHeader(rootPrefix, currentPage) {
    const header = document.getElementById("site-header");
    if (!header) return;

    const homeUrl = resolveRelPath(rootPrefix, "index.html");
    const loginUrl = resolveRelPath(rootPrefix, "pages/login.html");

    const navLinksHtml = NAV_ITEMS.map(function (item) {
      const url = resolveRelPath(rootPrefix, item.path);
      const isActive = currentPage === item.key;
      const activeClass = isActive ? " active" : "";
      const ariaCurrent = isActive ? ' aria-current="page"' : "";
      return (
        '<li class="nav-item">' +
          '<a class="nav-link' + activeClass + '" href="' + url + '"' + ariaCurrent + ">" +
            item.label +
          "</a>" +
        "</li>"
      );
    }).join("");

    const loginActiveClass = currentPage === "login" ? " active" : "";
    const loginAriaCurrent = currentPage === "login" ? ' aria-current="page"' : "";

    header.innerHTML =
      '<nav class="navbar navbar-expand-lg navbar-dark" aria-label="Primary Navigation">' +
        '<div class="container">' +
          '<a class="navbar-brand" href="' + homeUrl + '">' +
            '<span class="logo-placeholder" aria-hidden="true">SS</span>' +
            '<span class="brand-title">Student Shelter</span>' +
          "</a>" +
          '<button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#mainNavbar" ' +
            'aria-controls="mainNavbar" aria-expanded="false" aria-label="Toggle navigation">' +
            '<span class="navbar-toggler-icon"></span>' +
          "</button>" +
          '<div class="collapse navbar-collapse" id="mainNavbar">' +
            '<ul class="navbar-nav mx-auto my-2 my-lg-0">' +
              navLinksHtml +
            "</ul>" +
            '<div class="d-flex mt-2 mt-lg-0">' +
              '<a class="btn btn-amber px-4' + loginActiveClass + '" href="' + loginUrl + '"' + loginAriaCurrent + ">" +
                "Login" +
              "</a>" +
            "</div>" +
          "</div>" +
        "</div>" +
      "</nav>";
  }

  /**
   * Renders the shared footer inside <footer id="site-footer">.
   */
  function renderFooter(rootPrefix, currentPage) {
    const footer = document.getElementById("site-footer");
    if (!footer) return;

    const homeUrl = resolveRelPath(rootPrefix, "index.html");

    const socialHtml = SOCIAL_LINKS.map(function (social) {
      return (
        '<a class="social-link" href="' + social.href + '" aria-label="' + social.name + '" title="' + social.name + '">' +
          social.svg +
        "</a>"
      );
    }).join("");

    const footerLinksHtml = FOOTER_ITEMS.map(function (item, idx) {
      const url = resolveRelPath(rootPrefix, item.path);
      const isActive = currentPage === item.key;
      const activeClass = isActive ? ' class="active"' : "";
      const ariaCurrent = isActive ? ' aria-current="page"' : "";
      const separator = idx < FOOTER_ITEMS.length - 1 ? '<span class="footer-divider" aria-hidden="true">|</span>' : "";
      return '<a href="' + url + '"' + activeClass + ariaCurrent + ">" + item.label + "</a>" + separator;
    }).join("");

    footer.innerHTML =
      '<div class="container">' +
        '<div class="row gy-4 align-items-center justify-content-between">' +
          '<div class="col-md-6">' +
            '<a class="d-inline-flex align-items-center gap-3 text-decoration-none" href="' + homeUrl + '">' +
              '<span class="logo-placeholder" aria-hidden="true">SS</span>' +
              "<div>" +
                '<span class="brand-title d-block">Student Shelter</span>' +
                '<p class="footer-tagline">Your trusted student accommodation</p>' +
              "</div>" +
            "</a>" +
          "</div>" +
          '<div class="col-md-6 d-flex flex-column align-items-md-end gap-3">' +
            '<div class="social-links" aria-label="Social Media Links">' +
              socialHtml +
            "</div>" +
            '<nav class="footer-nav" aria-label="Footer Navigation">' +
              footerLinksHtml +
            "</nav>" +
          "</div>" +
        "</div>" +
        '<div class="footer-bottom d-flex flex-column flex-sm-row justify-content-between align-items-center gap-2">' +
          "<span>&copy; 2026 Student Shelter. All rights reserved.</span>" +
          "<span>Safe &amp; verified hostels near universities</span>" +
        "</div>" +
      "</div>";
  }

  /**
   * Adds subtle scroll shadow to the sticky header.
   */
  function initHeaderScrollEffect() {
    const header = document.getElementById("site-header");
    if (!header) return;

    function toggleShadow() {
      header.classList.toggle("is-scrolled", window.scrollY > 12);
    }

    toggleShadow();
    window.addEventListener("scroll", toggleShadow, { passive: true });
  }

  /**
   * Handles hostel search/filter logic on the Find a Hostel page.
   */
  function initHostelFilter() {
    const filterForm = document.getElementById("hostel-filter-form");
    const hostelCards = document.querySelectorAll("[data-hostel-card]");
    if (!filterForm || hostelCards.length === 0) return;

    const queryInput = document.getElementById("filter-university");
    const roomSelect = document.getElementById("filter-room-type");
    const budgetSelect = document.getElementById("filter-budget");
    const resetBtn = document.getElementById("filter-reset");
    const resultsCount = document.getElementById("filter-results-count");
    const emptyState = document.getElementById("filter-empty-state");

    // Pre-fill query from URL search params (e.g., from Home search form)
    const params = new URLSearchParams(window.location.search);
    if (params.has("university") && queryInput) {
      queryInput.value = params.get("university");
    }

    function applyFilters() {
      const searchTerm = (queryInput ? queryInput.value : "").trim().toLowerCase();
      const roomType = roomSelect ? roomSelect.value : "all";
      const maxBudget = budgetSelect ? Number(budgetSelect.value) : 0;

      let visibleCount = 0;

      hostelCards.forEach(function (card) {
        const text = (card.getAttribute("data-search") || "").toLowerCase();
        const types = (card.getAttribute("data-rooms") || "").toLowerCase();
        const price = Number(card.getAttribute("data-price") || 0);

        const matchesSearch = !searchTerm || text.includes(searchTerm);
        const matchesRoom = roomType === "all" || types.includes(roomType.toLowerCase());
        const matchesBudget = !maxBudget || price <= maxBudget;

        const isVisible = matchesSearch && matchesRoom && matchesBudget;
        card.classList.toggle("d-none", !isVisible);
        if (isVisible) visibleCount += 1;
      });

      if (resultsCount) {
        resultsCount.textContent = visibleCount + (visibleCount === 1 ? " hostel found" : " hostels found");
      }
      if (emptyState) {
        emptyState.classList.toggle("d-none", visibleCount > 0);
      }
    }

    filterForm.addEventListener("submit", function (event) {
      event.preventDefault();
      applyFilters();
    });

    [queryInput, roomSelect, budgetSelect].forEach(function (el) {
      if (el) {
        el.addEventListener("input", applyFilters);
        el.addEventListener("change", applyFilters);
      }
    });

    if (resetBtn) {
      resetBtn.addEventListener("click", function () {
        filterForm.reset();
        applyFilters();
      });
    }

    applyFilters();
  }

  /**
   * Handles Bootstrap-style client-side validation for Contact and Login forms.
   */
  function initFormValidation() {
    const forms = document.querySelectorAll(".needs-validation[data-demo-form]");
    forms.forEach(function (form) {
      form.addEventListener("submit", function (event) {
        event.preventDefault();
        event.stopPropagation();

        form.classList.add("was-validated");

        if (form.checkValidity()) {
          const feedbackId = form.getAttribute("data-feedback-target");
          const feedbackEl = feedbackId ? document.getElementById(feedbackId) : null;
          if (feedbackEl) {
            feedbackEl.classList.remove("d-none");
          }
          form.reset();
          form.classList.remove("was-validated");
        }
      });
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    const rootPrefix = getRootPrefix();
    const currentPage = getCurrentPageKey();

    renderHeader(rootPrefix, currentPage);
    renderFooter(rootPrefix, currentPage);
    initHeaderScrollEffect();
    initHostelFilter();
    initFormValidation();
  });
})();

args.CommandLine:
$root = "C:\Users\786\SEA_Group6_ShelterHome"
$htmlFiles = @("$root\index.html") + (Get-ChildItem "$root\pages\*.html" | ForEach-Object { $_.FullName })
Write-Output "=== HTML Files Found ==="
$htmlFiles | ForEach-Object { Write-Output $_ }

Write-Output "`n=== Checking Relative Links & Semantic Tags ==="
foreach ($file in $htmlFiles) {
    $dir = Split-Path $file -Parent
    $content = Get-Content $file -Raw
    $hasHeader = $content -match '<header\b'
    $hasMain = $content -match '<main\b'
    $hasFooter = $content -match '<footer\b'
    Write-Output "$((Split-Path $file -Leaf)): header=$hasHeader main=$hasMain footer=$hasFooter"

    $matches = [regex]::Matches($content, '(?:href|src|action)="([^"]+)"')
    foreach ($m in $matches) {
        $url = $m.Groups[1].Value
        if ($url -match '^https://cdn\.jsdelivr\.net/') { continue }
        if ($url.StartsWith('/') -or $url -match '^[a-zA-Z]+:') {
            Write-Error "Non-relative URL found in $file : $url"
        }
        $target = Join-Path $dir $url
        if (-not (Test-Path $target)) {
            Write-Error "Broken relative link in $file : $url -> $target"
        }
    }
}
Write-Output "`n=== Checking js/main.js relative links ==="
$js = Get-Content "$root\js\main.js" -Raw
[regex]::Matches($js, 'path:\s*"([^"]+)"') | ForEach-Object {
    $p = $_.Groups[1].Value
    $target = Join-Path $root $p
    Write-Output "JS nav path: $p -> exists=$(Test-Path $target)"
}
Write-Output "`n=== Checking images directory ==="
Get-ChildItem "$root\images" -Force | ForEach-Object { Write-Output $_.Name }
Write-Output "Verification complete."

