  // Format currency nicely as Rs 15,000
  function formatRupees(amount) {
    return "Rs " + Number(amount).toLocaleString("en-PK");
  }

  // Safely read favourite hostel IDs from localStorage (handles empty or corrupted storage)
  function loadFavorites() {
    try {
      const raw = window.localStorage.getItem(FAVORITES_STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .map(Number)
        .filter(function (id) {
          return HOSTELS.some(function (hostel) { return hostel.id === id; });
        });
    } catch (error) {
      return [];
    }
  }

  // Safely persist favourite hostel IDs to localStorage
  function saveFavorites(favoriteIds) {
    try {
      window.localStorage.setItem(FAVORITES_STORAGE_KEY, JSON.stringify(favoriteIds));
    } catch (error) {
      // Ignore storage quota or private browsing errors gracefully
    }
  }

  // Build heart SVG icon (filled when favourited, outline otherwise)
  function getHeartSvg(isFavorited) {
    if (isFavorited) {
      return '<svg width="18" height="18" fill="currentColor" viewBox="0 0 16 16" aria-hidden="true"><path fill-rule="evenodd" d="M8 1.314C12.438-3.248 23.534 4.735 8 15-7.534 4.736 3.562-3.248 8 1.314"/></svg>';
    }
    return '<svg width="18" height="18" fill="currentColor" viewBox="0 0 16 16" aria-hidden="true"><path d="m8 2.748-.717-.737C5.6.281 2.514.878 1.4 3.053c-.523 1.023-.641 2.5.314 4.385.92 1.815 2.834 3.989 6.286 6.357 3.452-2.368 5.365-4.542 6.286-6.357.955-1.886.838-3.362.314-4.385C13.486.878 10.4.28 8.717 2.01zM8 15C-7.333 4.868 3.279-3.04 7.824 1.143q.09.083.176.171a3 3 0 0 1 .176-.17C12.72-3.042 23.333 4.867 8 15"/></svg>';
  }

  document.addEventListener("DOMContentLoaded", function () {
    // Grab page elements
    const form = document.getElementById("hostel-filter-form");
    const citySelect = document.getElementById("select-city");
    const universitySelect = document.getElementById("select-university");
    const budgetSlider = document.getElementById("budget-range");
    const budgetInput = document.getElementById("budget-input");
    const budgetDisplay = document.getElementById("budget-value-display");

    const resultsHeading = document.getElementById("results-heading");
    const resultsCount = document.getElementById("results-count");
    const hostelsGrid = document.getElementById("hostels-grid");
    const savedHostelsCount = document.getElementById("saved-hostels-count");

    const noResultsBox = document.getElementById("state-no-results");
    const goBackBtn = document.getElementById("btn-go-back");

    const invalidInputBox = document.getElementById("state-invalid-input");
    const tryAgainBtn = document.getElementById("btn-try-again");

    // Modal elements for "View Details" (backdrop & Escape closing enabled)
    const detailModalEl = document.getElementById("hostelDetailModal");
    const detailModal = detailModalEl && window.bootstrap
      ? new window.bootstrap.Modal(detailModalEl, { backdrop: true, keyboard: true })
      : null;

    if (!form || !hostelsGrid) return;

    // Track favourite hostel IDs loaded from localStorage
    let favoriteIds = loadFavorites();

    function updateSavedCounter() {
      if (savedHostelsCount) {
        savedHostelsCount.textContent = String(favoriteIds.length);
      }
    }

    // 2. Populate City and University dropdowns dynamically from HOSTELS data
    function populateDropdowns() {
      const cities = [...new Set(HOSTELS.map(function (h) { return h.city; }))].sort();
      const universities = [...new Set(HOSTELS.map(function (h) { return h.university; }))].sort();

      cities.forEach(function (city) {
        const option = document.createElement("option");
        option.value = city;
        option.textContent = city;
        citySelect.appendChild(option);
      });

      universities.forEach(function (uni) {
        const option = document.createElement("option");
        option.value = uni;
        option.textContent = uni;
        universitySelect.appendChild(option);
      });
    }

    // 3. Render hostel cards into #hostels-grid from a given list
    function renderHostelCards(list) {
      hostelsGrid.innerHTML = "";

      list.forEach(function (hostel) {
        const col = document.createElement("div");
        col.className = "col-md-6";

        const badgeClass = hostel.gender === "Girls" ? "badge-amber" : "badge-teal";
        const isFav = favoriteIds.includes(hostel.id);
        const favClass = isFav ? " is-favorited" : "";
        const favLabel = isFav
          ? "Remove " + hostel.name + " from saved hostels"
          : "Save " + hostel.name + " to saved hostels";

        col.innerHTML =
          '<article class="shelter-card h-100 d-flex flex-column">' +
            '<div class="placeholder-box placeholder-box--card" role="img" aria-label="' + hostel.imagePlaceholder + '">' +
              '<span class="placeholder-box__label">Hostel Image Placeholder</span>' +
              '<span class="placeholder-box__sub">' + hostel.imagePlaceholder + '</span>' +
            "</div>" +
            '<div class="p-4 d-flex flex-column flex-grow-1">' +
              '<div class="d-flex justify-content-between align-items-center mb-2">' +
                '<span class="badge ' + badgeClass + '">' + hostel.gender + ' Hostel</span>' +
                '<div class="d-flex align-items-center gap-2">' +
                  '<span class="small text-muted">' + hostel.city + '</span>' +
                  '<button type="button" class="btn-favorite' + favClass + '" data-favorite-hostel="' + hostel.id + '" aria-pressed="' + isFav + '" aria-label="' + favLabel + '" title="Save to favourites">' +
                    getHeartSvg(isFav) +
                  "</button>" +
                "</div>" +
              "</div>" +
              '<h3 class="h5 fw-bold text-navy mb-1">' + hostel.name + '</h3>' +
              '<p class="small text-teal fw-semibold mb-2">Near ' + hostel.university + '</p>' +
              '<p class="small text-muted flex-grow-1 mb-3">' + hostel.description + '</p>' +
              '<div class="d-flex justify-content-between align-items-center pt-3 border-top">' +
                '<span class="fw-bold text-navy">' + formatRupees(hostel.price) + '/month</span>' +
                '<button type="button" class="btn btn-teal btn-sm" data-view-hostel="' + hostel.id + '">View Details</button>' +
              "</div>" +
            "</div>" +
          "</article>";

        hostelsGrid.appendChild(col);
      });
    }

    // Handle "View Details" modal & heart favourite toggle clicks inside #hostels-grid
    hostelsGrid.addEventListener("click", function (event) {
      // Toggle favourite heart button
      const favBtn = event.target.closest("[data-favorite-hostel]");
      if (favBtn) {
        const hostelId = Number(favBtn.getAttribute("data-favorite-hostel"));
        const hostel = HOSTELS.find(function (item) { return item.id === hostelId; });
        if (!hostel) return;

        const alreadySaved = favoriteIds.includes(hostelId);
        if (alreadySaved) {
          favoriteIds = favoriteIds.filter(function (id) { return id !== hostelId; });
        } else {
          favoriteIds.push(hostelId);
        }

        saveFavorites(favoriteIds);
        updateSavedCounter();

        const isNowSaved = !alreadySaved;
        favBtn.classList.toggle("is-favorited", isNowSaved);
        favBtn.setAttribute("aria-pressed", String(isNowSaved));
        favBtn.setAttribute(
          "aria-label",
          isNowSaved
            ? "Remove " + hostel.name + " from saved hostels"
            : "Save " + hostel.name + " to saved hostels"
        );
        favBtn.innerHTML = getHeartSvg(isNowSaved);
        return;
      }

      // Open modal with full details when "View Details" is clicked
      const viewBtn = event.target.closest("[data-view-hostel]");
      if (!viewBtn) return;

      const hostelId = Number(viewBtn.getAttribute("data-view-hostel"));
      const hostel = HOSTELS.find(function (item) { return item.id === hostelId; });
      if (!hostel || !detailModal) return;

      document.getElementById("modal-hostel-name").textContent = hostel.name;
      document.getElementById("modal-hostel-city").textContent = hostel.city;
      document.getElementById("modal-hostel-university").textContent = hostel.university;
      document.getElementById("modal-hostel-gender").textContent = hostel.gender;
      document.getElementById("modal-hostel-price").textContent = formatRupees(hostel.price) + "/month";
      document.getElementById("modal-hostel-description").textContent = hostel.description;

      const facilitiesList = document.getElementById("modal-hostel-facilities");
      if (facilitiesList) {
        facilitiesList.innerHTML = "";
        (hostel.facilities || []).forEach(function (facility) {
          const li = document.createElement("li");
          li.className = "facility-badge";
          li.textContent = facility;
          facilitiesList.appendChild(li);
        });
      }

      detailModal.show();
    });

    // Helper to switch cleanly between the 4 UI states
    function setViewState(stateName, matchingList) {
      // Hide state boxes and reset invalid input style first
      noResultsBox.classList.add("d-none");
      invalidInputBox.classList.add("d-none");
      budgetInput.classList.remove("input-invalid");

      if (stateName === "initial") {
        // State 1: Initial search — filters visible with all hostels shown
        resultsHeading.textContent = "Available Hostels";
        resultsCount.textContent = HOSTELS.length + " hostels";
        hostelsGrid.classList.remove("d-none");
        renderHostelCards(HOSTELS);
      } else if (stateName === "results") {
        // State 2: Search results — "Hostels Found" heading with matching cards
        resultsHeading.textContent = "Hostels Found";
        resultsCount.textContent = matchingList.length + (matchingList.length === 1 ? " hostel" : " hostels");
        hostelsGrid.classList.remove("d-none");
        renderHostelCards(matchingList);
      } else if (stateName === "empty") {
        // State 3: No results — show "No Hostel Found! Try different filters." + Go Back
        resultsHeading.textContent = "Hostels Found";
        resultsCount.textContent = "0 hostels";
        hostelsGrid.classList.add("d-none");
        noResultsBox.classList.remove("d-none");
      } else if (stateName === "invalid") {
        // State 4: Invalid input — show "Please enter a valid budget" + Try Again
        resultsHeading.textContent = "Available Hostels";
        resultsCount.textContent = "Invalid budget";
        hostelsGrid.classList.add("d-none");
        invalidInputBox.classList.remove("d-none");
        budgetInput.classList.add("input-invalid");
      }
    }

    // Keep range slider, number box, and badge label in sync
    function syncBudgetUI(value) {
      const numeric = Number(value);
      if (!isNaN(numeric) && numeric >= 5000 && numeric <= 30000) {
        budgetSlider.value = numeric;
        budgetDisplay.textContent = formatRupees(numeric);
      } else {
        budgetDisplay.textContent = value === "" ? "Not set" : "Rs " + value;
      }
    }

    budgetSlider.addEventListener("input", function () {
      budgetInput.value = budgetSlider.value;
      budgetInput.classList.remove("input-invalid");
      syncBudgetUI(budgetSlider.value);
    });

    budgetInput.addEventListener("input", function () {
      budgetInput.classList.remove("input-invalid");
      syncBudgetUI(budgetInput.value.trim());
    });

    // Reset filters back to State 1 (Initial search)
    function resetFiltersToInitial() {
      citySelect.value = "all";
      universitySelect.value = "all";
      budgetSlider.value = 30000;
      budgetInput.value = 30000;
      syncBudgetUI(30000);
      setViewState("initial");
    }

    // 4. Filter hostels when Search is clicked
    form.addEventListener("submit", function (event) {
      event.preventDefault();

      const rawBudget = budgetInput.value.trim();
      const maxBudget = Number(rawBudget);

      // State 4 check: budget missing or outside Rs 5,000 - Rs 30,000
      if (rawBudget === "" || isNaN(maxBudget) || maxBudget < 5000 || maxBudget > 30000) {
        setViewState("invalid");
        return;
      }

      const selectedCity = citySelect.value;
      const selectedUniversity = universitySelect.value;

      const filtered = HOSTELS.filter(function (hostel) {
        const matchesCity = selectedCity === "all" || hostel.city === selectedCity;
        const matchesUni = selectedUniversity === "all" || hostel.university === selectedUniversity;
        const matchesBudget = hostel.price <= maxBudget;
        return matchesCity && matchesUni && matchesBudget;
      });

      if (filtered.length === 0) {
        setViewState("empty");
      } else {
        setViewState("results", filtered);
      }
    });

    // "Go Back" button (State 3 -> State 1)
    goBackBtn.addEventListener("click", function () {
      resetFiltersToInitial();
    });

    // "Try Again" button (State 4 -> State 1 with valid budget restored)
    tryAgainBtn.addEventListener("click", function () {
      budgetSlider.value = 30000;
      budgetInput.value = 30000;
      syncBudgetUI(30000);
      setViewState("initial");
      budgetInput.focus();
    });

    // 5. Initialize dropdowns, saved counter, and check URL ?q= parameter on page load
    populateDropdowns();
    updateSavedCounter();
    syncBudgetUI(budgetInput.value);

    const urlParams = new URLSearchParams(window.location.search);
    const queryParam = (urlParams.get("q") || "").trim();

    if (queryParam) {
      const qLower = queryParam.toLowerCase();

      // Pre-select matching city or university dropdown if there is an exact/partial match
      Array.from(citySelect.options).forEach(function (opt) {
        if (opt.value !== "all" && opt.value.toLowerCase().includes(qLower)) {
          citySelect.value = opt.value;
        }
      });
      Array.from(universitySelect.options).forEach(function (opt) {
        if (opt.value !== "all" && opt.value.toLowerCase().includes(qLower)) {
          universitySelect.value = opt.value;
        }
      });

      const queryMatches = HOSTELS.filter(function (hostel) {
        return (
          hostel.city.toLowerCase().includes(qLower) ||
          hostel.university.toLowerCase().includes(qLower) ||
          hostel.name.toLowerCase().includes(qLower)
        );
      });

      if (queryMatches.length === 0) {
        setViewState("empty");
      } else {
        setViewState("results", queryMatches);
      }
    } else {
      // State 1: Initial view showing all hostels
      setViewState("initial");
    }
  });
})();

