// Keyboard accessibility: close expanded mobile menu with Escape and return focus to toggler
const navCollapseEl = document.getElementById("mainNavbar");
const togglerBtn = document.getElementById("navbar-toggler-btn");
if (navCollapseEl && togglerBtn && window.bootstrap) {
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && navCollapseEl.classList.contains("show")) {
      const collapseInstance = window.bootstrap.Collapse.getOrCreateInstance(navCollapseEl);
      collapseInstance.hide();
      togglerBtn.focus();
    }
  });
}
